import json,re,html,pathlib
d=json.load(open('products/services/first-receipt/hn-route/raw/nov2026-thread.json'))
out=[]
for c in d.get('children',[]):
  t=re.sub(r'\s+',' ',html.unescape(re.sub(r'<[^>]+>',' ',c.get('text') or ''))).strip()
  out.append({'id':c.get('id'),'created_at':c.get('created_at'),'seeking_freelancer':bool(re.search(r'seeking\s+freelancer',t[:80],re.I)),'has_email':bool(re.search(r'[\w.+-]+@[\w-]+\.[\w.]+|\[at\]|\(at\)| at .* dot ',t,re.I)),'text':t[:1500]})
p=pathlib.Path('products/services/first-receipt/hn-route/thread-extract.json');p.write_text(json.dumps({'thread':'https://news.ycombinator.com/item?id=50338744','title':d.get('title'),'created_at':d.get('created_at'),'top_level':len(out),'comments':out},indent=1,ensure_ascii=False))
for o in out:
  if o['seeking_freelancer']: print(json.dumps(o,ensure_ascii=False))
print('total',len(out),'seeking',sum(o['seeking_freelancer'] for o in out))
